    (N'FUNC-035', N'functional', N'不知道业务名词在库里叫什么，助手先做什么？', N'先 search_metadata 按关键字查模块/表/字段/动作，拿到模块号或字段键后再 describe_module / get_form_schema，不靠猜。', N'list_my_capabilities', N'list', N'{"question":"不知道业务名词在库里叫什么，助手先做什么？","expected":"先 search_metadata 按关键字查模块/表/字段/动作，拿到模块号或字段键后再 describe_module / get_form_schema，不靠猜。","sources":["SearchMetadataTool","MetadataSearchGateway"],"expect_tools":["list_my_capabilities"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-036', N'functional', N'search_metadata 的命中受什么限制？', N'按当前用户的模块浏览权过滤：看不到的模块，其表/字段/动作一并隐藏；结果有上限且如实说明截断。', N'search_metadata', N'list', N'{"question":"search_metadata 的命中受什么限制？","expected":"按当前用户的模块浏览权过滤：看不到的模块，其表/字段/动作一并隐藏；结果有上限且如实说明截断。","sources":["MetadataSearchGateway"],"expect_tools":["search_metadata"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-037', N'functional', N'页面处境带 moduleId 时，助手为什么能直接说出模块字段？', N'ChatService 向 IModuleBriefProvider 取运行时装配的模块结构摘要（权限过滤后的主表/明细表关键字段），注入数据区并声明不是指令。', N'describe_module', N'list', N'{"question":"页面处境带 moduleId 时，助手为什么能直接说出模块字段？","expected":"ChatService 向 IModuleBriefProvider 取运行时装配的模块结构摘要（权限过滤后的主表/明细表关键字段），注入数据区并声明不是指令。","sources":["ModuleBriefProvider","ChatService"],"expect_tools":["describe_module"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-038', N'functional', N'动作执行后如何证明真的落库？', N'执行成功后在权限与数据范围内按主键回读关键字段，随结果卡回显；回读失败不影响写入结论。', N'', N'', N'{"question":"动作执行后如何证明真的落库？","expected":"执行成功后在权限与数据范围内按主键回读关键字段，随结果卡回显；回读失败不影响写入结论。","sources":["AssistantRecordActionService","AssistantActionRowResult"]}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-039', N'functional', N'助手质量看板统计什么？', N'近 N 天的会话/消息、工具调用成功/失败/未知、拒绝与未知工具、单条回复的工具调用数分桶、token、成本与反馈；只读聚合，不含正文与参数。', N'', N'', N'{"question":"助手质量看板统计什么？","expected":"近 N 天的会话/消息、工具调用成功/失败/未知、拒绝与未知工具、单条回复的工具调用数分桶、token、成本与反馈；只读聚合，不含正文与参数。","sources":["AssistantQualityView","AssistantQualityController"]}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-040', N'functional', N'工具失败在质量看板里怎么判定？', N'新数据按 TOOL_CALLS_JSON 的 Ok 计成功/失败；旧数据没有 Ok 按未知结果计，不伪造；rejected: 单独计。', N'', N'', N'{"question":"工具失败在质量看板里怎么判定？","expected":"新数据按 TOOL_CALLS_JSON 的 Ok 计成功/失败；旧数据没有 Ok 按未知结果计，不伪造；rejected: 单独计。","sources":["AssistantQualityView","ToolCallSummary"]}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-041', N'functional', N'业务页和配置页发给模型的工具有什么不同？', N'业务页不摆配置写与元数据管理工具，配置页不摆记录写、单据动作与批核请求卡；未知页面不裁剪。裁剪只影响声明，权限仍由工具内部重判。', N'', N'', N'{"question":"业务页和配置页发给模型的工具有什么不同？","expected":"业务页不摆配置写与元数据管理工具，配置页不摆记录写、单据动作与批核请求卡；未知页面不裁剪。裁剪只影响声明，权限仍由工具内部重判。","sources":["AssistantToolSetPolicy","ChatService"]}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-042', N'functional', N'确认型自定义动作会被助手直接执行吗？', N'不会。CONFIRM_TAG=1 的动作只生成确认卡、本轮不执行；用户点确认后由界面直接调既有动作端点。CONFIRM_TAG=0 才可由助手执行。', N'list_document_actions,preview_document_action', N'view', N'{"question":"确认型自定义动作会被助手直接执行吗？","expected":"不会。CONFIRM_TAG=1 的动作只生成确认卡、本轮不执行；用户点确认后由界面直接调既有动作端点。CONFIRM_TAG=0 才可由助手执行。","sources":["ApplyDocumentActionTool","DocumentActionGateway"],"expect_tools":["list_document_actions","preview_document_action"],"page":"view"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-043', N'functional', N'知识库检索结果如何标注来源？', N'kb_search 返回 kb://doc/{id}#c{n} 引用，回答必须标注来源；机制问题走 describe_mechanism，规范与设计动因走 kb_search，冲突以服务端元数据为准。', N'kb_search', N'list', N'{"question":"知识库检索结果如何标注来源？","expected":"kb_search 返回 kb://doc/{id}#c{n} 引用，回答必须标注来源；机制问题走 describe_mechanism，规范与设计动因走 kb_search，冲突以服务端元数据为准。","sources":["KbSearchTool","ChatService"],"expect_tools":["kb_search"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-044', N'functional', N'知识库入库前会做什么检查？', N'敏感信息扫描（证件/银行卡/手机号/凭据）与业务引用逐条权限复核；命中即整篇拒入，不静默放行。', N'', N'', N'{"question":"知识库入库前会做什么检查？","expected":"敏感信息扫描（证件/银行卡/手机号/凭据）与业务引用逐条权限复核；命中即整篇拒入，不静默放行。","sources":["KbIngestScanner","KbController"]}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-045', N'functional', N'质量看板里的“分桶”是模型工具轮数吗？', N'不是。它是单条回复产生的工具调用数（0/1/2/3/4/5+）；一次回复可能在同一轮里产生多个调用，不能用它直接判断 MaxToolRounds。', N'', N'', N'{"question":"质量看板里的“分桶”是模型工具轮数吗？","expected":"不是。它是单条回复产生的工具调用数（0/1/2/3/4/5+）；一次回复可能在同一轮里产生多个调用，不能用它直接判断 MaxToolRounds。","sources":["AssistantQualityView","AssistantQualityCallBucket"]}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-046', N'functional', N'口径计算会因为某个用户没勾选某列而算不出来吗？', N'不会。口径的列白名单取权限口径（字段级禁看、成本与保密、FIELDS.IS_VISIBLE、必须真有物理列），不取该用户的列选择（SYS_USER_COLUMN 只是显示偏好）。', N'resolve_metric', N'list', N'{"question":"口径计算会因为某个用户没勾选某列而算不出来吗？","expected":"不会。口径的列白名单取权限口径（字段级禁看、成本与保密、FIELDS.IS_VISIBLE、必须真有物理列），不取该用户的列选择（SYS_USER_COLUMN 只是显示偏好）。","sources":["MetricFieldWhitelist","ResolveMetricTool"],"expect_tools":["resolve_metric"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-047', N'functional', N'用户说「营业额」时要先枚举口径吗？', N'不必。resolve_metric 的 metric_id 可直接写业务词：命中唯一已确认口径即计算并在结果里标注按哪个业务词解析；命中多条会列出候选并要求改用标识，不猜口径。', N'resolve_metric', N'list', N'{"question":"用户说「营业额」时要先枚举口径吗？","expected":"不必。resolve_metric 的 metric_id 可直接写业务词：命中唯一已确认口径即计算并在结果里标注按哪个业务词解析；命中多条会列出候选并要求改用标识，不猜口径。","sources":["ResolveMetricTool","MetricRepository.SearchConfirmedAsync"],"expect_tools":["resolve_metric"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-048', N'functional', N'模型把维度写成中文名（如「订单日期」）会怎样？', N'按 FIELDS.F_DESC 映射回标识 ORDER_DATE 后照常计算；映射不到时报出全部可用维度（带中文名）。成功结果的依据链也带「可用维度」，模型不必再枚举口径。', N'resolve_metric', N'list', N'{"question":"模型把维度写成中文名（如「订单日期」）会怎样？","expected":"按 FIELDS.F_DESC 映射回标识 ORDER_DATE 后照常计算；映射不到时报出全部可用维度（带中文名）。成功结果的依据链也带「可用维度」，模型不必再枚举口径。","sources":["ResolveMetricTool","MetricFieldWhitelist.ReadLabelsAsync"],"expect_tools":["resolve_metric"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-049', N'functional', N'维度过滤被拒时可以把过滤条件去掉重算吗？', N'不行。省略过滤等于把问题换成另一个范围（9 月变成全部时间），会答出另一个问题的数字；必须按「可用维度」改正后重试，确实做不到就如实说明。', N'resolve_metric', N'list', N'{"question":"维度过滤被拒时可以把过滤条件去掉重算吗？","expected":"不行。省略过滤等于把问题换成另一个范围（9 月变成全部时间），会答出另一个问题的数字；必须按「可用维度」改正后重试，确实做不到就如实说明。","sources":["ChatService","ResolveMetricTool"],"expect_tools":["resolve_metric"],"page":"list"}', N'DRAFT', N'official', 1, N''),
    (N'FUNC-050', N'functional', N'「这张单多少钱」怎么用口径取数？', N'用 resolve_metric 的 record 传该模块的完整主键（键为定义里的主键列、值来自 search_records 的 _keys），服务端按主键等值过滤后计算；只给单号会被拒绝，因为主键是单别+单号，单给单号会在跨单别重号时静默放大范围。', N'resolve_metric', N'view', N'{"question":"「这张单多少钱」怎么用口径取数？","expected":"用 resolve_metric 的 record 传该模块的完整主键（键为定义里的主键列、值来自 search_records 的 _keys），服务端按主键等值过滤后计算；只给单号会被拒绝，因为主键是单别+单号，单给单号会在跨单别重号时静默放大范围。","sources":["ResolveMetricTool","WorkbenchDefinition.MasterPkOrder"],"expect_tools":["resolve_metric"],"page":"view"}', N'DRAFT', N'official', 1, N''),
    (N'INFR-001', N'inference', N'这张客户订单能按时交付吗', N'沿订单→明细→产品→库存/在途采购/生产工单→历史履约综合判断，给出结论与依据链。', N'', N'', N'{"question":"这张客户订单能按时交付吗","expected":"沿订单→明细→产品→库存/在途采购/生产工单→历史履约综合判断，给出结论与依据链。","sources":["search_records:1405","get_record_detail:1405","resolve_metric:inventory_qty","get_module_flow:1405"],"required_sources":["search_records:1405","get_record_detail:1405","resolve_metric:inventory_qty","get_module_flow:1405"]}', N'DRAFT', N'official', 1, N''),
