-- ============================================================================
-- EOS.ERP migration 458：助手评估用例（模块 3106 · 评估用例）
-- ----------------------------------------------------------------------------
--  把"评估尺子"从仓库文件搬进库：管理员通过模块权限决定**谁能维护它**，改动落审计。
--  设计要点：
--   · 单表纯主表模块（M_URL=/workbench + MASTER_TABLE）⇒ 直接获得列表/统一表单/
--     选择列/导出/字段级权限/审计，不需要新增权限代码，也不需要新增前端页面；
--   · 权限默认**不授予任何组/用户**：可见性与维护权由管理员在 2306「用户权限设定」分配；
--   · 仓库里的 AssistantEval/*.jsonl 继续作为**离线门禁的输入**（CI 无库），
--     库内用例是运行期数据；两者不要求逐字节一致（用户环境没有 git），
--     需要留档时用列表导出即可。
--   · 审阅状态（REVIEW_STATUS）与生命周期位（APPROVED/FINISHED）分开：前者是本表的
--     业务语义（DRAFT/SUBMITTED/APPROVED/RETIRED），后者只满足框架对单据表的列约定。
--
--  种子：现有 8 个种子文件一次性导入（诊断层 30 条已审阅 = APPROVED，其余为 DRAFT）。
-- ============================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;

IF DB_NAME() <> N'EOS.ERP'
    THROW 51930, N'本脚本只允许在 EOS.ERP 数据库上执行。', 1;

IF OBJECT_ID(N'dbo.MODULES', N'U') IS NULL
    THROW 51931, N'MODULES 不存在，迁移终止。', 1;

/* ---------- 1. 建表 ---------- */
IF OBJECT_ID(N'dbo.ASSISTANT_EVAL_CASE', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.ASSISTANT_EVAL_CASE
    (
        CASE_ID        nvarchar(40)    NOT NULL,
        LAYER          nvarchar(20)    NOT NULL,
        QUESTION       nvarchar(1000)  NULL,
        EXPECTED       nvarchar(2000)  NULL,
        EXPECT_TOOLS   nvarchar(400)   NULL,
        PAGE_TYPE      nvarchar(20)    NULL,
        PAYLOAD_JSON   nvarchar(max)   NULL,
        REVIEW_STATUS  nvarchar(20)    NOT NULL CONSTRAINT DF_ASSISTANT_EVAL_CASE_REVIEW_STATUS DEFAULT N'DRAFT',
        ORIGIN         nvarchar(20)    NULL,
        CASE_VERSION   int             NOT NULL CONSTRAINT DF_ASSISTANT_EVAL_CASE_CASE_VERSION DEFAULT 1,
        REMARK         nvarchar(1000)  NULL,
        APPROVED       bit             NOT NULL CONSTRAINT DF_ASSISTANT_EVAL_CASE_APPROVED DEFAULT 0,
        APPROVED_BY    nvarchar(20)    NULL,
        APPROVED_TIME  datetime        NULL,
        FINISHED       bit             NOT NULL CONSTRAINT DF_ASSISTANT_EVAL_CASE_FINISHED DEFAULT 0,
        FINISHED_BY    nvarchar(20)    NULL,
        FINISHED_TIME  datetime        NULL,
        CREATED_BY     nvarchar(20)    NOT NULL CONSTRAINT DF_ASSISTANT_EVAL_CASE_CREATED_BY DEFAULT N'',
        CREATED_TIME   datetime        NOT NULL CONSTRAINT DF_ASSISTANT_EVAL_CASE_CREATED_TIME DEFAULT GETDATE(),
        MODIFIED_BY    nvarchar(20)    NULL,
        MODIFIED_TIME  datetime        NULL,
        CONSTRAINT PK_ASSISTANT_EVAL_CASE PRIMARY KEY CLUSTERED (CASE_ID)
    );

    CREATE INDEX IX_ASSISTANT_EVAL_CASE_LAYER_STATUS
        ON dbo.ASSISTANT_EVAL_CASE (LAYER, REVIEW_STATUS) INCLUDE (CASE_VERSION);

    PRINT N'== ASSISTANT_EVAL_CASE 已创建 ==';
END
ELSE
    PRINT N'== ASSISTANT_EVAL_CASE 已存在，跳过建表 ==';

/* ---------- 2. 模块 3106 · 评估用例（挂在「助手」根节点 31 下） ---------- */
IF NOT EXISTS (SELECT 1 FROM dbo.MODULES WHERE M_IDX = 3106)
BEGIN
         REMARK, MODIFIED_BY, MODIFIED_TIME, M_ALIAS, DETAIL_NO_FIELDS, DETAIL_NO_SAVE,
         NOT_BACK_FIELDS, NOT_BACK_FIELDS_M, AUTO_APPROVE, ERROR_NO_SAVE, SEARCH_1, SEARCH_2,
         SORT_FIELDS, IF_COPY, M_ICON, FORM_OPEN_MODE, FORM_DIALOG_WIDTH, FORM_DIALOG_HEIGHT,
         APPROVE_ENABLED, UNIFIED_FORM_ENABLED, UNIFIED_FORM_EDIT_ENABLED)
    VALUES
        (3106, N'评估用例', N'/workbench', 31, 31, 40, 1, N'ASSISTANT_EVAL_CASE', NULL, NULL,
         N'助手评估用例（尺子）：按层次维护问句/期望工具链/诊断样本与配置样本。'
         + N'可见性与维护权**不预置**，由管理员在「用户权限设定」按模块分配；'
         + N'审阅状态（REVIEW_STATUS）与批核位分开，本模块不接流程。',
         N'458', GETDATE(), NULL, NULL, NULL, NULL, NULL, 0, 0, 1, 0,
         N'[CASE_ID] ASC', 0, NULL, NULL, NULL, NULL, 0, 1, 1);

    PRINT N'== 模块 3106 已登记 ==';
END
ELSE
    PRINT N'== 模块 3106 已存在，跳过登记 ==';

/* ---------- 3. 字段元数据 ---------- */
IF NOT EXISTS (SELECT 1 FROM dbo.FIELDS WHERE T_ID = N'ASSISTANT_EVAL_CASE')
BEGIN
         IS_VERIFY, VERIFY_INDEX, IS_PK, IS_READONLY, IS_VISIBLE, IS_VIRTUAL, IS_QUERY,
         IS_DEFAULT_FIELDS, CAN_COPY, MODIFIED_BY, MODIFIED_TIME)
    VALUES
        (N'ASSISTANT_EVAL_CASE', N'CASE_ID',       N'用例编号', N'nvarchar', 140, N'left',   N'left',  1, 0,  1, 0, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'LAYER',         N'层次',     N'nvarchar', 110, N'left',   N'left',  1, 1,  0, 0, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'QUESTION',      N'问句',     N'nvarchar', 300, N'left',   N'left',  0, 2,  0, 0, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'EXPECTED',      N'期望结果', N'nvarchar', 300, N'left',   N'left',  0, 3,  0, 0, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'EXPECT_TOOLS',  N'期望工具', N'nvarchar', 180, N'left',   N'left',  0, 4,  0, 0, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'PAGE_TYPE',     N'页面类型', N'nvarchar', 90,  N'center', N'left',  0, 5,  0, 0, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'REVIEW_STATUS', N'审阅状态', N'nvarchar', 90,  N'center', N'center',1, 6,  0, 0, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'ORIGIN',        N'来源',     N'nvarchar', 90,  N'center', N'left',  0, 7,  0, 0, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'CASE_VERSION',  N'版本',     N'int',      60,  N'center', N'right', 0, 8,  0, 1, 1, 0, 1, 1, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'PAYLOAD_JSON',  N'载荷',     N'nvarchar', 300, N'left',   N'left',  0, 9,  0, 0, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'REMARK',        N'说明',     N'nvarchar', 240, N'left',   N'left',  0, 10, 0, 0, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'APPROVED',      N'批核状态', N'bit',      79,  N'center', N'center',0, 11, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'APPROVED_BY',   N'批核人',   N'nvarchar', 90,  N'center', N'left',  0, 12, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'APPROVED_TIME', N'批核时间', N'datetime', 130, N'center', N'left',  0, 13, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'FINISHED',      N'结案状态', N'bit',      78,  N'center', N'center',0, 14, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'FINISHED_BY',   N'结案人',   N'nvarchar', 90,  N'center', N'left',  0, 15, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'FINISHED_TIME', N'结案时间', N'datetime', 130, N'center', N'left',  0, 16, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'CREATED_BY',    N'建立人',   N'nvarchar', 90,  N'center', N'left',  0, 17, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'CREATED_TIME',  N'建立时间', N'datetime', 130, N'center', N'left',  0, 18, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'MODIFIED_BY',   N'修改人',   N'nvarchar', 90,  N'center', N'left',  0, 19, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE()),
        (N'ASSISTANT_EVAL_CASE', N'MODIFIED_TIME', N'修改时间', N'datetime', 130, N'center', N'left',  0, 20, 0, 1, 1, 0, 1, 0, 1, N'458', GETDATE());

    PRINT N'== ASSISTANT_EVAL_CASE 字段元数据已登记 ==';
END
ELSE
    PRINT N'== ASSISTANT_EVAL_CASE 字段元数据已存在，跳过 ==';


/* ---------- 4. 种子：现有 8 个种子文件一次性导入 ---------- */
-- ============================================================================
-- 迁移 458 的种子数据部分（由 scripts/oneshot/gen-458-eval-case-seed.ps1 生成）
-- 来源：EOS.API.Tests/AssistantEval 下 8 个种子文件；诊断层 30 条已审阅（APPROVED），
--       其余层为代码 grounded 的候选（DRAFT）。
-- 只在表为空时导入一次：此后用例的增删改都在库里改（模块 3106），不回灌本脚本。
-- ============================================================================
SET NOCOUNT ON;
IF NOT EXISTS (SELECT 1 FROM dbo.ASSISTANT_EVAL_CASE)
BEGIN
    ;
    PRINT N'== 评估用例种子已导入 ==';
END
ELSE
    PRINT N'== 评估用例表非空，跳过种子导入 ==';

